import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"零信任架构","description":"","frontmatter":{"title":"零信任架构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zero-trust-architecture.md","filePath":"cs/zero-trust-architecture.md","lastUpdated":1789023840000}'),p={name:"cs/zero-trust-architecture.md"};function u(_,a,E,m,P,f){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="零信任架构" tabindex="-1">零信任架构 <a class="header-anchor" href="#零信任架构" aria-label="Permalink to &quot;零信任架构&quot;">​</a></h1><div class="epigraph"><p>零信任架构把每请求的认证、授权与加密当默认，网络位置降为弱信号。策略引擎、身份、设备姿态组成控制平面。它是 NIST 的架构语言，不是某厂商产品名。</p><footer>—— Rose et al., NIST SP 800-207</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/risk-quantification">风险量化</a>要减情景。缺口是<strong>架构</strong>：前课<a href="/cs/vpn-zero-trust">VPN 对零信任</a>已对照管道。本课收 SP 800-207 组件。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>隐式信任区过大。缺口：PE/PA、持续评估、微分段。身份来自本课程身份单元。</p><h3 id="遗留" tabindex="-1">遗留 <a class="header-anchor" href="#遗留" aria-label="Permalink to &quot;遗留&quot;">​</a></h3><p>不能一次关掉 VPN。迁移是并行控制。</p><p><span class="marginnote">SP 800-207。纵深防御下一课把多层写进同一画面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画控制平面与数据平面。下一课纵深防御。</p>',12)),(e(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E8%BA%AB%E4%BB%BD%E4%B8%8E%E8%AE%BE%E5%A4%87%22%5D%20--%3E%20PE%5B%22%E7%AD%96%E7%95%A5%E5%BC%95%E6%93%8E%22%5D%0A%20%20PE%20--%3E%20PA%5B%22%E7%AD%96%E7%95%A5%E6%89%A7%E8%A1%8C%E7%82%B9%22%5D%0A%20%20PA%20--%3E%20RES%5B%22%E8%B5%84%E6%BA%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>请求级授权。纵深下一课强调仍要多层，零信任不是单层银弹。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写厂商对照表。纵深防御下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量化指出隐式信任贵；零信任改默认。</li><li>策略引擎每请求评估。</li><li>位置弱信号；身份单元零件接上。</li><li>下一课纵深防御。</li><li>出处：NIST SP 800-207；<a href="/cs/vpn-zero-trust">vpn-zero-trust</a>。</li></ul>',8))])}const B=i(p,[["render",u]]);export{T as __pageData,B as default};
